                                font-size: 1rem;
                                font-weight: 600;
                                color: #2c3e50;
                            }

                            p {
                                margin: 0;
                                font-size: 0.9rem;
                                color: #6b7280;
                                line-height: 1.4;
                            }
                        }
                    }
                }

                .empty-insights {
                    text-align: center;
                    padding: 2rem;
                    color: #6b7280;

                    p {
                        margin: 0;
                        font-size: 0.9rem;
