            border-radius: 20px;
            padding: 2rem;
            box-shadow: 0 20px 40px rgba(102, 126, 234, 0.1);

            .section-header {
                margin-bottom: 2rem;

                h2 {
                    font-size: 1.5rem;
                    font-weight: 600;
                    color: #2c3e50;
                    margin: 0;
