                            color: #2c3e50;
                            min-width: 35px;
                        }
                    }
                }

                .add-goal-btn {
                    width: 100%;
                    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
                    color: white;
                    border: none;
                    padding: 1rem;
                    border-radius: 12px;
                    font-size: 1rem;
                    font-weight: 600;
                    cursor: pointer;
                    transition: all 0.3s ease;

                    &:hover {
                        transform: translateY(-2px);
                        box-shadow: 0 8px 25px rgba(102, 126, 234, 0.3);
                    }
                }
            }
        }
    }

    /* Dark Mode Styles */
    &.dark-mode {
        .dashboard-header,
        .summary-cards .summary-card,
        .charts-section,
        .transactions-section,
        .insights-section .insight-card,
        .goals-section .goal-item .goal-progress .progress-bar {
            background: linear-gradient(135deg, rgba(30, 41, 59, 0.9) 0%, rgba(51, 65, 85, 0.9) 100%);
            border-color: rgba(255, 255, 255, 0.1);
            color: #f1f5f9;

            h1, h2, h3, h4, p {
                color: #f1f5f9;
            }
        }

        .summary-cards .summary-card .card-content .trend.neutral {
            color: #94a3b8;
        }
    }

    /* Responsive Design */
    @media (max-width: 1200px) {
        .dashboard-grid {
            grid-template-columns: 1fr;
        }

        .summary-cards {
            grid-template-columns: 1fr;
        }
    }

