import React, { useEffect, useState } from 'react'
import { useGlobalContext } from '../../context/globalContext';
import { InnerLayout } from '../../styles/Layouts';
import { motion } from 'framer-motion';
import {
  TrendingUp,
  TrendingDown,
  DollarSign,
  Target,
  Sparkles,
  Bot,
  Plus
} from 'lucide-react';
import Chart from '../Chart/Chart';

function Dashboard() {
    const { totalExpenses, incomes, expenses, totalIncome, totalBalance, getIncomes, getExpenses, getBudgetSuggestions } = useGlobalContext()
    const [suggestions, setSuggestions] = useState([])
    const [recentTransactions, setRecentTransactions] = useState([])

    useEffect(() => {
        getIncomes()
        getExpenses()
        fetchSuggestions()
        loadRecentTransactions()
    }, [])

    const fetchSuggestions = async () => {
        const sugg = await getBudgetSuggestions()
        setSuggestions(sugg)
    }

    const loadRecentTransactions = () => {
        const combined = [
            ...incomes.map(income => ({ ...income, type: 'income' })),
            ...expenses.map(expense => ({ ...expense, type: 'expense' }))
        ];
        combined.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
        setRecentTransactions(combined.slice(0, 5));
    }

    const getGreeting = () => {
        const hour = new Date().getHours();
        if (hour < 12) return "Good morning";
        if (hour < 18) return "Good afternoon";
        return "Good evening";
    }

    return (
        <div className="min-h-screen bg-gray-50">
            <InnerLayout>
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.6 }}
                    className="mb-8"
                >
                    <p className="text-gray-500 text-sm mb-2">{getGreeting()}, Chandra</p>
                    <h1 className="text-3xl font-semibold text-gray-900 tracking-tight">
                        Your Financial Overview
                    </h1>
                </motion.div>

                {/* Summary Cards */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.6, delay: 0.1 }}
                    className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8"
                >
                    {/* Total Income */}
                    <motion.div
                        whileHover={{ y: -2 }}
                        transition={{ duration: 0.2 }}
                        className="bg-white border border-gray-200 rounded-xl p-6"
                    >
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm font-medium text-gray-600 mb-1">Total Income</p>
                                <p className="text-2xl font-semibold text-gray-900 tabular-nums">
                                    ${totalIncome().toLocaleString()}
                                </p>
                            </div>
                            <div className="w-12 h-12 bg-green-100 rounded-lg flex items-center justify-center">
                                <TrendingUp className="w-6 h-6 text-green-600" />
                            </div>
                        </div>
                        <div className="flex items-center mt-4">
                            <TrendingUp className="w-4 h-4 text-green-500 mr-1" />
                            <span className="text-sm text-green-600 font-medium">+12% from last month</span>
                        </div>
                    </motion.div>

                    {/* Total Expenses */}
                    <motion.div
                        whileHover={{ y: -2 }}
                        transition={{ duration: 0.2 }}
                        className="bg-white border border-gray-200 rounded-xl p-6"
                    >
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm font-medium text-gray-600 mb-1">Total Expenses</p>
                                <p className="text-2xl font-semibold text-gray-900 tabular-nums">
                                    ${totalExpenses().toLocaleString()}
                                </p>
                            </div>
                            <div className="w-12 h-12 bg-red-100 rounded-lg flex items-center justify-center">
                                <TrendingDown className="w-6 h-6 text-red-600" />
                            </div>
                        </div>
                        <div className="flex items-center mt-4">
                            <TrendingDown className="w-4 h-4 text-red-500 mr-1" />
                            <span className="text-sm text-red-600 font-medium">-8% from last month</span>
                        </div>
                    </motion.div>

                    {/* Net Balance */}
                    <motion.div
                        whileHover={{ y: -2 }}
                        transition={{ duration: 0.2 }}
                        className="bg-white border border-gray-200 rounded-xl p-6"
                    >
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm font-medium text-gray-600 mb-1">Net Balance</p>
                                <p className={`text-2xl font-semibold tabular-nums ${
                                    totalBalance() >= 0 ? 'text-green-600' : 'text-red-600'
                                }`}>
                                    ${Math.abs(totalBalance()).toLocaleString()}
                                </p>
                            </div>
                            <div className="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center">
                                <DollarSign className="w-6 h-6 text-blue-600" />
                            </div>
                        </div>
                        <p className="text-sm text-gray-500 mt-4">Current balance</p>
                    </motion.div>
                </motion.div>

                {/* Main Content Grid */}
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Charts Section */}
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.6, delay: 0.2 }}
                        className="lg:col-span-2"
                    >
                        <div className="bg-white border border-gray-200 rounded-xl p-6">
                            <div className="flex items-center justify-between mb-6">
                                <h2 className="text-lg font-semibold text-gray-900">Spending Analytics</h2>
